function saveStudy(id,patch){if(!topic(id))return;const entry={...studyEntry(id),...patch,updatedAt:new Date().toISOString()};state.study[id]=entry;saveStore(K.study,state.study)}
function topicStudyStats(){const vals=Object.values(state.study);return {started:vals.filter(v=>v.status==='studying'||v.status==='mastered').length,mastered:vals.filter(v=>v.status==='mastered').length,notes:vals.filter(v=>(v.notes||'').trim()).length}}
function dueStudyTopics(){const now=Date.now();const arr=Object.entries(state.study).filter(([id,e])=>topic(id)&&e.status!=='todo'&&e.reviewAt&&Date.parse(e.reviewAt)<=now).map(([id])=>topic(id));const wrong=D.practice.filter(q=>state.answers[q.id]&&!state.answers[q.id].correct&&Date.parse(state.study[q.topicId]?.updatedAt||0)<Date.parse(state.answers[q.id].time||0)).map(q=>topic(q.topicId)).filter(Boolean);return [...new Map([...arr,...wrong].map(t=>[t.id,t])).values()].slice(0,5)}
function nextReviewAt(days){const d=new Date();d.setDate(d.getDate()+days);return d.toISOString()}
function normalizeSearch(s){return String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim()}
function officialResults(){
 const term=normalizeSearch(state.officialTerm);
 let found=state.officialData;
 if(state.officialTopicId){
  const t=topic(state.officialTopicId);
  if(t){const keywords=(t.keywords||[]).map(normalizeSearch).filter(x=>x.length>=3);
   found=found.filter(q=>{const content=normalizeSearch([q.title,q.context,q.question,q.alternativesIntroduction,q.subject,q.topic].filter(Boolean).join(' '));return keywords.some(k=>content.includes(k))});
  }
 }
 if(!term)return found;
 return found.filter(q=>normalizeSearch([q.title,q.context,q.question,q.alternativesIntroduction,q.subject,q.topic].filter(Boolean).join(' ')).includes(term))
}

