function levelName(v){return {'basico':'Básico','intermediario':'Intermediário','avancado':'Avançado'}[v]||''}
function stat(label,n,small,ic){return `<div class="stat"><div class="stat-label">${icon(ic)}${label}</div><div class="number">${n}</div><div class="small">${small}</div></div>`}
function allStats(){const totalDone=Object.values(state.done).filter(Boolean).length;const ans=Object.values(state.answers);const right=ans.filter(x=>x.correct).length;return {done:totalDone,answered:ans.length,right,rate:ans.length?Math.round(100*right/ans.length):null}}
function pageHead(kicker,title,subtitle,cta=''){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1 class="page-title">${title}</h1><p class="page-sub">${subtitle}</p></div>${cta}</div>`}
function topicRank(t,i){let max=t.total?Math.round(t.total*.5):100;return `<div class="rank-row" role="button" tabindex="0" data-act="topic" data-id="${t.id}"><div class="rank-index">${String(i+1).padStart(2,'0')}</div><div><div class="rank-name">${esc(t.title)}</div><div class="rank-disc">${esc(t.discipline)}</div></div><div class="rank-bar"><span style="width:${Math.min(100,Math.max(7,t.percent*2))}%"></span></div><div class="rank-count">${t.count==null?'—':fmt(t.count)}</div>${icon('chevron')}</div>`}
function getBalancedTop(){return ['mat','ling','nat','hum'].map(area => [...D.topics].filter(t=>t.area===area).sort((a,b)=>b.count-a.count)[0]).filter(Boolean)}
function buildPool(area){const arr=D.topics.filter(t=>t.area===area);const discs=[...new Set(arr.map(t=>t.discipline))];const result=[];let r=0;while(result.length<arr.length){for(const d of discs){const match=arr.find(t=>t.discipline===d&&t.rank===r+1);if(match)result.push(match)}r++}return result}
const pools=Object.fromEntries(areas.map(a=>[a,buildPool(a)]));
function studyDays(n){return {3:[1,3,6],4:[1,2,4,6],5:[1,2,3,5,6],6:[1,2,3,4,5,6],7:[0,1,2,3,4,5,6]}[n]||[1,2,3,5,6]}
function weeksCount(){return Math.max(4,Math.round((state.profile?.months||2)*4.345))}
function buildSchedule(){if(!state.profile)return [];
  const prof=state.profile, days=studyDays(Number(prof.days)), total=weeksCount();
  const rotations=prof.focus==='equilibrado'?['mat','ling','nat','hum','red']:['mat','ling','nat','hum','red',prof.focus,prof.focus];
  const counters={mat:0,ling:0,nat:0,hum:0,red:0};const plans=[];let overall=0;
  for(let w=0;w<total;w++){
    let entries=[];
    for(let k=0;k<days.length;k++){
      let area=rotations[overall%rotations.length],arr=pools[area],cycles=counters[area]++;
      const maxBreadth=prof.months<=2?Math.min(arr.length,area==='red'?5:10):prof.months<=4?Math.min(arr.length,area==='red'?5:18):arr.length;
      // Concentrate on high-frequency topics in shorter plans; introduce more breadth in longer plans.
      const index=(cycles+Math.floor(cycles/(area==='red'?4:Math.max(4,Math.round(maxBreadth*.6)))))%maxBreadth;
      const t=arr[index]; const id=`w${w}d${days[k]}`;
      const date=new Date();date.setHours(12,0,0,0);date.setDate(date.getDate()+((8-date.getDay())%7) + (days[k]===0?6:days[k]-1) + w*7);
      const mins=Number(prof.minutes);
      const theoryShare=prof.level==='basico'?.60:prof.level==='intermediario'?.42:.24;
      const theory=Math.max(10,Math.round(mins*theoryShare/5)*5);
      entries.push({id,date,topic:t,area,minutes:mins,theory:Math.min(theory,mins-10),practice:mins-Math.min(theory,mins-10),week:w,weekday:days[k]});overall++;
    }plans.push(entries)
  }return plans;
}
